#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int x;
    struct Node *next;
} Node;

Node *new_node(int x) {
    Node *p = (Node *)malloc(sizeof(Node));
    if (p == NULL) {
        return NULL;
    }
    p->x = x;
    p->next = NULL;
    return p;
}

int main(void) {
    Node *head = new_node({a});
    Node *second = new_node({b});
    if (head == NULL || second == NULL) {
        return 1;
    }
    head->next = second;

    Node *cur = head;
    while (cur != NULL) {
        printf("%d -> ", cur->x);
        cur = cur->next;
    }
    printf("NULL\n");

    free(second);
    free(head);
    return 0;
}
